96	    /** Maximum number of owners a single city may hold before further creations are rejected. */
97	    static final long MAX_OWNERS_PER_CITY = 50;
98	
99	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
100	    static final long MAX_OWNERS_PER_DAY = 100;
101	
102	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
103	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
