160	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
161	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
162	        if (existingOwnerId != null) {
163	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
164	            if (existingOwner != null) {
165	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
166	            }
167	        }
168	        this.normalizeAddress(ownerFieldsDto);
169	        this.ownerFieldsValidator.validate(ownerFieldsDto);
170	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
175	        LocalDate serverDate = LocalDate.now();
176	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
177	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
178	        }
179	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
180	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
181	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
182	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
183	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
184	        }
185	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
186	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
188	        }
189	        if (owner.getPostcode() != null) {
190	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
191	        }
192	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
193	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
194	        }
195	        Owner softMatch = this.clinicService.findSoftMatchOf(owner);
196	        if (softMatch != null) {
197	            owner.setPossibleDuplicateOf(softMatch.getId());
198	        }
199	        this.clinicService.saveOwner(owner);
200	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
201	        this.ownerAuditLogger.logCreated(owner);
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        headers.setLocation(UriComponentsBuilder.newInstance()
204	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
205	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
206	    }
