235	        currentOwner.setAddress(ownerFieldsDto.getAddress());
236	        currentOwner.setCity(ownerFieldsDto.getCity());
237	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
238	        currentOwner.setLastName(ownerFieldsDto.getLastName());
239	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
240	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
241	        this.clinicService.saveOwner(currentOwner);
242	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Transactional
